"""Bound-aware compiler fuzz against both references."""
import random, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from brute import compare, brute_image
from fado_ref import fado_image
from ebpf.create_dfa import create, registry_columns

def gen(rng, names, pool):
    def path(maxlen):
        return ','.join(rng.choice(names) for _ in range(rng.randint(0,maxlen)))
    def pred(d):
        if d>=rng.randint(1,4) or rng.random()<0.4:
            if rng.random()<0.55:
                return 'match(%s)'%path(4)
            op, p = rng.choice(pool)
            return '%s(%s)'%(op, ','.join(p))
        if rng.random()<0.25: return 'not(%s)'%pred(d+1)
        return '(%s %s %s)'%(pred(d+1),rng.choice(['and','or']),pred(d+1))
    rules=[]
    for _ in range(rng.randint(0,4)):
        rules.append('%s %s;'%(pred(0),rng.choice(['allow','allow','drop'])))
    return ' '.join(rules)

seed=int(sys.argv[1]); count=int(sys.argv[2]); mode=sys.argv[3] if len(sys.argv)>3 else 'brute'
rng=random.Random(seed)
if mode=='brute':
    names=['A','B','C']; dw=dc=5
else:
    names=['A','B','C','D','E']; dw=dc=4
ops=['startswith','endswith','contains']
pool=[(rng.choice(ops), tuple(rng.choice(names) for _ in range(rng.randint(0,4)))) for _ in range(4)]
labels=rng.sample(range(1,4294967294),len(names))
reg=[{'name':n,'label':labels[i]} for i,n in enumerate(names)]
cols,colmap=registry_columns(reg)
bad=skip=done=0
for i in range(count):
    p=gen(rng,names,pool)
    try:
        got=create(p,cols,colmap); got={'accept':list(got.accept),'rows':[list(r) for r in got.rows]}
    except Exception as e:
        skip+=1; continue
    try:
        if mode=='brute': ref=brute_image(p,cols,colmap,dw,dc)
        else: ref=fado_image(p,cols,colmap)
    except Exception as e:
        skip+=1; continue
    done+=1
    if got!=ref:
        bad+=1
        print('DIFF',repr(p)); print(' got',got['accept'],got['rows'][:6]); print(' ref',ref['accept'],ref['rows'][:6])
        if bad>2: break
print('fuzz2[%s] seed %d checked %d bad %d skip %d'%(mode,seed,done,bad,skip))
PYEOF
